<h1><?= e(__('Tạo tài khoản')) ?></h1><p class="text-muted mb-4"><?= e(__('Lưu chỗ ở yêu thích và quản lý chuyến đi ở một nơi.')) ?></p><form method="post" action="<?= e(url('/register')) ?>"><?= csrf_field() ?><input type="hidden" name="next" value="<?= e($next??'') ?>"><div class="form-group"><label for="full_name"><?= e(__('Họ và tên')) ?></label><input class="form-control" id="full_name" name="full_name" autocomplete="name" value="<?= e($old['full_name']??'') ?>" required></div><div class="form-group"><label for="email">Email</label><input class="form-control" id="email" autocomplete="email" type="email" name="email" value="<?= e($old['email']??'') ?>" required></div><div class="form-group"><label for="phone"><?= e(__('Số điện thoại')) ?></label><input class="form-control" id="phone" name="phone" type="tel" autocomplete="tel" value="<?= e($old['phone']??'') ?>"></div><div class="form-group"><label for="password"><?= e(__('Mật khẩu (ít nhất 8 ký tự)')) ?></label><input class="form-control" id="password" type="password" name="password" autocomplete="new-password" required minlength="8"></div><button class="btn btn-primary btn-block" type="submit"><?= e(__('Tạo tài khoản')) ?></button></form><p class="text-center mt-4"><?= e(__('Đã có tài khoản?')) ?> <a href="<?= e(url('/login'.(!empty($next)?'?'.http_build_query(['next'=>$next]):''))) ?>"><?= e(__('Đăng nhập')) ?></a></p>

